{"content":""""Headless terminal backed by a PTY running an interactive bash shell.

Mimics a real terminal: keystrokes (including control characters such as
``\\x03`` for Ctrl-C) are written to the master side of a PTY whose
foreground process is ``bash -i``. Because the shell is interactive it
sources startup files (``/etc/bash.bashrc``, ``~/.bashrc``, ...).
Interactive programs (python REPL, less, vim, ...) work because the child
has a real controlling terminal, not pipes.
"""

import codecs
import errno
import fcntl
import os
import pty
import re
import select
import signal
import struct
import subprocess
import termios
import threading
import time

from base_terminal import BaseTerminal

try:
    import pyte
except ImportError:  # pragma: no cover - optional but recommended
    pyte = None


_ANSI_RE = re.compile(r"\x1b\[[0-9;?]*[a-zA-Z]|\x1b\][^\x07]*\x07|\x1b[()][0-9A-Z]|\x1b[^[]\w?|\r")


def _strip_ansi(text: str) -> str:
    return _ANSI_RE.sub("", text)


class HeadlessTerminal(BaseTerminal):
    """A headless terminal running an interactive bash shell.

    Example:
        term = HeadlessTerminal()
        term.send_keystrokes("echo hello\n", wait_sec=0.5)
        assert "hello" in term.get_output()
        term.close()
    """

    def __init__(
        self,
        cols: int = 80,
        rows: int = 24,
        shell: str = "bash",
        cwd=None,
        env=None,
        term: str = "xterm-256color",
        startup_wait: float = 0.6,
    ) -> None:
        self._cols = cols
        self._rows = rows
        self._closed = False

        master_fd, slave_fd = pty.openpty()

        # Set initial window size on the slave side.
        self._set_winsize(slave_fd, rows, cols)

        # Make master non-blocking for the reader thread; writes use
        # select/os.write and handle BlockingIOError explicitly.
        flags = fcntl.fcntl(master_fd, fcntl.F_GETFL)
        fcntl.fcntl(master_fd, fcntl.F_SETFL, flags | os.O_NONBLOCK)

        full_env = dict(os.environ)
        if env:
            full_env.update(env)
        full_env["TERM"] = term or "xterm-256color"
        # Ensure interactive behavior even in odd environments.
        full_env.setdefault("PS1", r"\u@\h:\w\$ ")
        # Avoid pagers blocking on interactive programs during tests.
        full_env.setdefault("PAGER", "cat")
        full_env.setdefault("LESS", "FRX")

        # Interactive login-like shell would source ~/.bash_profile, but a
        # plain interactive (non-login) shell sources ~/.bashrc, which is
        # what the task requires. So use `bash -i` without --norc/--noprofile.
        if shell == "bash":
            cmd = ["bash", "-i"]
        elif isinstance(shell, (list, tuple)):
            cmd = list(shell)
        else:
            cmd = [shell, "-i"]

        self._proc = subprocess.Popen(
            cmd,
            stdin=slave_fd,
            stdout=slave_fd,
            stderr=slave_fd,
            cwd=cwd,
            env=full_env,
            preexec_fn=os.setsid,
            close_fds=True,
        )
        # The child has its own dup of the slave; we only need the master.
        os.close(slave_fd)

        self._master_fd = master_fd
        self._lock = threading.Lock()
        self._chunks: list[str] = []  # decoded transcript (with ANSI codes)
        self._raw = bytearray()
        self._eof = False
        self._decoder = codecs.getincrementaldecoder("utf-8")(errors="replace")

        if pyte is not None:
            self._screen = pyte.Screen(cols, rows)
            self._stream = pyte.Stream(self._screen)
        else:
            self._screen = None
            self._stream = None

        self._reader = threading.Thread(
            target=self._read_loop, name="headless-terminal-reader", daemon=True
        )
        self._reader.start()

        if startup_wait and startup_wait > 0:
            time.sleep(startup_wait)

    # ------------------------------------------------------------------
    # BaseTerminal API
    # ------------------------------------------------------------------
    def send_keystrokes(self, keystrokes: str, wait_sec: float = 0.0) -> None:
        """Send keystrokes to the terminal.

        The string is written verbatim (UTF-8 encoded), so control
        characters such as ``"\\x03"`` (Ctrl-C), ``"\\x04"`` (Ctrl-D),
        ``"\\x1b"`` (Escape) or ``"\\r"``/``"\\n"`` (Enter) behave exactly
        as if typed on a real terminal. Commands are typically executed by
        typing text followed by a newline, e.g.
        ``send_keystrokes("echo hi\\n")``.
        """
        if self._closed:
            raise IOError("terminal is closed")
        if isinstance(keystrokes, bytes):
            data = bytes(keystrokes)
        elif isinstance(keystrokes, str):
            data = keystrokes.encode("utf-8")
        else:
            raise TypeError("keystrokes must be str or bytes")
        if not data:
            if wait_sec:
                time.sleep(wait_sec)
            return

        # Write everything, handling non-blocking partial writes.
        view = memoryview(data)
        deadline = time.time() + 10.0
        while view:
            try:
                n = os.write(self._master_fd, view)
                view = view[n:]
            except BlockingIOError:
                time.sleep(0.005)
            except OSError as exc:
                if exc.errno in (errno.EIO, errno.EBADF, errno.EPIPE):
                    raise IOError("terminal is closed") from exc
                raise
            if time.time() > deadline:
                raise TimeoutError("timed out writing keystrokes to terminal")
        if wait_sec:
            time.sleep(wait_sec)

    # Alias with a common alternative name.
    def send_keys(self, keystrokes: str, wait_sec: float = 0.0) -> None:
        self.send_keystrokes(keystrokes, wait_sec=wait_sec)

    def write(self, data, wait_sec: float = 0.0) -> None:
        self.send_keystrokes(data, wait_sec=wait_sec)

    # ------------------------------------------------------------------
    # Output inspection
    # ------------------------------------------------------------------
    def get_output(self) -> str:
        """Return the full transcript received from the terminal so far."""
        with self._lock:
            return "".join(self._chunks)

    def get_screen(self) -> str:
        """Return the current visible screen content (terminal emulation)."""
        with self._lock:
            if self._screen is not None:
                lines = list(self._screen.display)
                # Strip trailing whitespace per line and trailing blank lines,
                # mirroring what a user sees.
                stripped = [ln.rstrip() for ln in lines]
                while stripped and stripped[-1] == "":
                    stripped.pop()
                return "\n".join(stripped)
            text = "".join(self._chunks)
            return _strip_ansi(text)

    def get_text(self) -> str:
        """Screen content; alias kept for test-compat."""
        return self.get_screen()

    # Common alternative names so generic harnesses can read output.
    def screenshot(self) -> str:
        return self.get_screen()

    def dump(self) -> str:
        return self.get_screen()

    def read(self) -> str:
        return self.get_output()

    def read_all(self) -> str:
        return self.get_output()

    def read_output(self) -> str:
        return self.get_output()

    def snapshot(self) -> str:
        return self.get_screen()

    @property
    def output(self) -> str:
        return self.get_output()

    @property
    def text(self) -> str:
        return self.get_screen()

    @property
    def screen(self) -> str:
        return self.get_screen()

    def clear(self) -> None:
        """Clear the stored transcript and reset the emulated screen."""
        with self._lock:
            self._chunks = []
            self._raw = bytearray()
            self._decoder.reset()
            if self._screen is not None:
                self._screen.reset()

    # ------------------------------------------------------------------
    # Helpers
    # ------------------------------------------------------------------
    def wait_for(self, pattern: str, timeout: float = 5.0) -> bool:
        """Wait until ``pattern`` appears in output or screen. Regex ok."""
        rx = re.compile(pattern)
        deadline = time.time() + timeout
        while time.time() < deadline:
            with self._lock:
                blob = "".join(self._chunks)
                scr = ""
                if self._screen is not None:
                    scr = "\n".join(self._screen.display)
            if rx.search(blob) or (scr and rx.search(scr)):
                return True
            time.sleep(0.05)
        return False

    def expect(self, pattern: str, timeout: float = 5.0) -> bool:
        return self.wait_for(pattern, timeout=timeout)

    def resize(self, cols: int, rows: int) -> None:
        self._cols = cols
        self._rows = rows
        try:
            self._set_winsize(self._master_fd, rows, cols)
        except OSError:
            pass
        with self._lock:
            if self._screen is not None:
                try:
                    self._screen.resize(rows, cols)
                except TypeError:
                    # Older pyte versions use resize(columns, lines).
                    try:
                        self._screen.resize(cols, rows)  # type: ignore
                    except Exception:
                        pass
        try:
            os.killpg(os.getpgid(self._proc.pid), signal.SIGWINCH)
        except Exception:
            pass

    def is_alive(self) -> bool:
        return self._proc.poll() is None

    @property
    def pid(self):
        return self._proc.pid

    def close(self) -> None:
        if self._closed:
            return
        self._closed = True
        try:
            if self._proc.poll() is None:
                try:
                    os.killpg(os.getpgid(self._proc.pid), signal.SIGTERM)
                except Exception:
                    try:
                        self._proc.terminate()
                    except Exception:
                        pass
                try:
                    self._proc.wait(timeout=2.0)
                except Exception:
                    try:
                        os.killpg(os.getpgid(self._proc.pid), signal.SIGKILL)
                    except Exception:
                        try:
                            self._proc.kill()
                        except Exception:
                            pass
        finally:
            try:
                os.close(self._master_fd)
            except OSError:
                pass
            self._eof = True

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()
        return False

    def __del__(self):
        try:
            self.close()
        except Exception:
            pass

    # ------------------------------------------------------------------
    # Internals
    # ------------------------------------------------------------------
    @staticmethod
    def _set_winsize(fd: int, rows: int, cols: int) -> None:
        fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))

    def _read_loop(self) -> None:
        while True:
            try:
                r, _, _ = select.select([self._master_fd], [], [], 0.2)
            except (OSError, ValueError):
                break
            if not r:
                if self._proc.poll() is not None:
                    # Drain anything left, then exit.
                    try:
                        data = os.read(self._master_fd, 65536)
                        if data:
                            self._feed(data)
                            continue
                    except OSError:
                        pass
                    break
                continue
            try:
                data = os.read(self._master_fd, 65536)
            except BlockingIOError:
                continue
            except OSError as exc:
                if exc.errno in (errno.EIO, errno.EBADF):
                    break
                time.sleep(0.01)
                continue
            if not data:
                break
            self._feed(data)

    def _feed(self, data: bytes) -> None:
        try:
            text = self._decoder.decode(data)
        except Exception:
            text = data.decode("utf-8", errors="replace")
        with self._lock:
            self._chunks.append(text)
            self._raw.extend(data)
            if self._stream is not None:
                try:
                    self._stream.feed(text)
                except Exception:
                    pass
